# -*- coding: utf-8 -*-
s = open('case/tree.html', encoding='utf-8').read()


def rep(a, b, n=1):
    global s
    assert s.count(a) == n, (a, s.count(a))
    s = s.replace(a, b)


def addcard(cid, html):
    global s
    i = s.find(f'id="{cid}"')
    j = s.find('</div></details>', i)
    assert i > 0 and j > 0
    s = s[:j] + html + s[j:]


rep('<span class="pname">Соколова Клавдия Алексеевна</span><span class="pyrs">? – ?</span>',
    '<span class="pname">Соколова (Мотова) Клавдия Алексеевна</span><span class="pyrs">≈1890 – ?</span>')
rep('{ id: "klavdiya",  g: 5, x: 411,  n: "Клавдия Алексеевна", s: "Соколова",',
    '{ id: "klavdiya",  g: 5, x: 411,  n: "Клавдия Алексеевна", s: "Мотова · ≈1890",')
rep('фамилия в распознанном тексте неясна («Мохова» или «Мотова»), на скан ещё не смотрели.',
    '20 лет; фамилия разделена переносом «Мо-/това» (09.11 сверено по скану, см. ниже).')
addcard('klavdiya', '<p><b>09.11.2026. Девичья фамилия — Мотова.</b> На скане записи № 122 фамилия перенесена: «Клавдія Алексѣева Мо-/това». Первая буква второй строки написана так же, как «т» у этого писаря в слове «Почетн.», и иначе, чем «х» в «Михалевской». Распознанный текст «Мохова» — ошибка. Так же прочитал и сторонний исследователь. Невесте 20 лет, значит, она родилась около 1889–1890 года. В том же селе Михалеве есть Алексей Ильин Мотов (восприемник 1899 года). Он подходит в отцы по имени и месту, но это <b>только гипотеза</b>. По указателю (сам скан не смотрели) в Михалеве 04.05.1915 умерла Евдокия Васильева Мотова, 70 лет, приход Космодамианской церкви погоста Гвоздня (ЦГАМО ф.43 оп.1 д.141 л.131). Родство с Клавдией не установлено, но это второй приход, где стоит искать Мотовых. Следующий шаг — её рождение около 1889–1890 года в Михалеве или Гвоздне.</p>')
rep('Просмотрены глазами рождения Челухоевской церкви с декабря 1913 по октябрь 1914 года: у Елескиных девять детей, но Ольги среди них нет.',
    'Просмотрены глазами рождения Челухоевской церкви с декабря 1914 по октябрь 1915 года: у Елескиных девять детей, но Ольги среди них нет. <b>Исправлено 09.11:</b> сначала эти сканы ошибочно отнесли к 1914 году. На самом деле это начало книги 1915 года: у декабрьских рождений помечено «1914 г.», а крещены дети в январе. Рождения января–ноября 1914 года здесь отсутствуют, так что отрицательный результат за 1914 год снят. По «Хронографу Кузбасса на 2018 год» (с. 18) в Кемерове сохранились Челухоевские книги 1890–91, 1893–94, 1898–1907, 1910–12, 1915 и 1917–18; книг 1913–1914 там нет.')
rep('ск.203–250 (рождения 1914)</a>', 'ск.203–250 (рождения XII.1914–X.1915)</a>')
rep('в Челухоевской — за 1912 и 1916–18.', 'в Челухоевской — за 1912, 1915 и 1916–18.')
addcard('asya', '<p><b>09.11.2026, новая наводка (не проверена).</b> По сообщению на форуме ВГД от 25.04.2024: РГВА ф.37976 оп.1 д.180 — Розин Маркел Александрович, 1888 года рождения, послужной список и пенсионная переписка за 1935–1946 годы, 8 листов. Опись мы не сверяли и дело не смотрели. Если в деле есть семейные сведения, оно может подтвердить, что Маркел — отец Аси. Пока он остаётся кандидатом. Надёжнее всего установит родителей запись о рождении 1923 года.</p>')
addcard('pesterevy', '<p><b>09.11.2026, маршрут к рождению Иосифа (≈1857–58).</b> ГАТО ф.170 оп.9 д.601 — метрические книги церквей Кузнецкого округа за 1857 год, 531 лист (официальная карточка ГАТО, по стороннему отчёту). Запасные дела: 170-9-633 (1858) и 170-9-661 (1859). На FamilySearch Салаирская часть 1857 года, по указателю, — DGS 007469955, около снимка 171. Запись не найдена; координаты не сверены.</p>')
addcard('ivand', '<p><b>09.11.2026, адреса дел (по описи ГАБО ф.247 оп.1, с. 4–5, по стороннему отчёту).</b> Кроме д.114 (1826–1836, 358 л.), полезны д.113 (1810–1825, 278 л.) — для брака родителей и д.117 (1850–1856, 375 л.) — для брака Ивана в 1853 году. Сами акты не прочитаны. Если брака родителей в Старом не окажется, это его не опровергнет: могли венчаться в приходе невесты.</p>')
i = s.find('id="ivanbatsov"')
j = s.find('</p>\n      </div></details>', i)
assert j > 0
s = s[:j + 4] + '<p><b>09.11.2026, ещё один адрес (по стороннему отчёту, не проверен).</b> В работе С. А. Пинчука (раздел 13, сноски 46–48) уточнена дата дела РГВИА ф.9196 оп.243, св.27, д.120, лл.24–32 — 28.07.1854. Параллельная ссылка — АВПРИ, ф. «Канцелярия», 1853, д.164, л.234 (опись не указана). Тождество с болгарским Иваном Бацовым по-прежнему не доказано. Решить его может формуляр В. И. Бацова 1912 года.</p>' + s[j + 4:]
open('case/tree.html', 'w', encoding='utf-8').write(s)
print('ok')
